/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
/// This is the services class for executing the AMEX rejected payment lines process.
/// </summary>
class METAMEXMoveRejectedLinesService extends SysOperationServiceBase
{
    
}

Method.Source:
    /// <summary>
    /// Service operation to set the batch tasks for posting journal and creating free text invoices.
    /// </summary>
    /// <param name = "_contract"><c>METAMEXMoveRejectedLinesContract</c></param>
    /// <returns><c>METAMEXMoveRejectedLinesResponse</c></returns>
    [AifCollectionTypeAttribute('return', Types::Class, classStr(METAMEXMoveRejectedLinesResponse))]
    public METAMEXMoveRejectedLinesResponse runOperation(METAMEXMoveRejectedLinesContract _contract)
    {      
         
        METAMEXMoveRejectedLinesResponse    response = new METAMEXMoveRejectedLinesResponse();
        if (this.validate(_contract, response).parmSuccess())
        {
            changecompany(_contract.parmDataArea())
            {
                try
                {
                    BatchHeader batchHeader = BatchHeader::getCurrentBatchHeader();
                    if (batchHeader == null)
                    {
                        batchHeader = batchHeader::construct();
                    }
                    batchHeader.parmCaption(strFmt("@MET:AMEXMoveRejectedLinesMenuItemAction"));
                    
                    //Add Batch task to Remove/Delete payments lines and post journal 
                    // create new controller for posting journal
                    SysOperationServiceController rejectLinescontroller = this.moveRejectedLinesController(_contract);
                    batchHeader.addTask(rejectLinescontroller);

                    //Add Batch task to post free text invoices 
                    SysOperationServiceController postInvcontroller = this.PostFreeTextInvController(_contract);
                    batchHeader.addTask(postInvcontroller);
                    batchHeader.addDependency(postInvcontroller, rejectLinescontroller, BatchDependencyStatus::FinishedOrError);

                    batchHeader.save();

                    response.parmSuccess(true);
                    response.parmMessage(strfmt("@MET:METAMEXRejectLinesBatchSuccessMsg",CustParameters::find().METAMEXPaymJournalNum));
                    info(response.parmMessage());
                }
                catch (Exception::CLRError)
                {
                    System.Exception interopException = CLRInterop::getLastException();

                    response.parmSuccess(false);
                    response.parmMessage(interopException.ToString());
                }
            }
        }
        else
        {
            info(response.parmMessage());
        }

        return response;

    }

    /// <summary>
    /// Validating the data contract parameters.
    /// </summary>
    /// <param name = "_request"><c>METAMEXMoveRejectedLinesContract</c> class instance.</param>
    /// <param name = "_response"><c>METAMEXMoveRejectedLinesResponse</c> class instance</param>
    /// <returns><c>METAMEXMoveRejectedLinesResponse</c> class instance.</returns>
    private  METAMEXMoveRejectedLinesResponse validate(
                    METAMEXMoveRejectedLinesContract _request, 
                    METAMEXMoveRejectedLinesResponse _response)
    {
        LedgerJournalTable journalTable =   LedgerJournalTable::find(CustParameters::find().METAMEXPaymJournalNum);

        _response.parmSuccess(true);

        if (!journalTable)
        {
            _response.parmSuccess(false);
            _response.parmMessage("@SYS19282");
        }
        else if(journalTable.Posted)
        {
            _response.parmSuccess(false);
            _response.parmMessage(strFmt("@MET:METAMEXJournalAlreadyPostedError", journalTable.JournalNum));
        }
        else if(!LedgerJournalName::find(_request.parmJournalName()))
        {
            _response.parmSuccess(false);
            _response.parmMessage(strFmt("@MET:METAMEXInvalidJournalNameError", _request.parmJournalName()));
        }

        _request.parmPrevJournalNum(journalTable.JournalNum);

        return _response;
    }

    /// <summary>
    /// This method does the job to remove/delete rejected lines and post the journal.
    /// </summary>
    /// <param name = "_contract"><c>METAMEXMoveRejectedLinesContract</c> class instance.</param>
    private void moveRejectedLinesTask(METAMEXMoveRejectedLinesContract _contract)
    {
        LedgerJournalTable    journalTable    =   LedgerJournalTable::find(CustParameters::find().METAMEXPaymJournalNum);

        #OCCRetryCount
        try
        {
            if (!journalTable)
            {
                return;
            }
            if(_contract.parmAction() == METAMEXAction::Delete)
            {
                LedgerJournalTrans  ledgerJournalTrans;
                if (journalTable)
                {
                    ttsbegin;
                    delete_from ledgerJournalTrans where
                    ledgerJournalTrans.JournalNum == journalTable.JournalNum
                    && ledgerJournalTrans.PaymentStatus == CustVendPaymStatus::Rejected;
                    LedgerJournalPost::post(journalTable, tableNum(LedgerJournalTable), NoYes::No, true, false);
                    ttscommit;
                }

            }
            else if(_contract.parmAction() == METAMEXAction::Remove)
            {
                LedgerJournalPost::post(journalTable, tableNum(LedgerJournalTable), NoYes::Yes, true, false);
            }
            else
            {
                throw error(Error::wrongUseOfFunction("@MET:AMEXMoveRejectLinesFunctionError"));
            }

            //Update new LedgerJournalTable with the parameters passed.Because we are unable to pass these parametes while journal posting 
            //we have to do the taks here. 
            journalTable.reread();
            LedgerJournalTable newJournalTable = LedgerJournalTable::find(CustParameters::find().METAMEXPaymJournalNum, true);
            if (journalTable.Posted
                && journalTable.JournalNum != newJournalTable.JournalNum)

            {
                ttsbegin;
                newJournalTable.JournalName = _contract.parmJournalName();
                newJournalTable.initFromLedgerJournalName(newJournalTable.JournalName);
                newJournalTable.Name = _contract.parmJournalDesc();
                newJournalTable.SystemBlocked = NoYes::Yes;
                newJournalTable.doUpdate();
                ttscommit;
            }
        
        }

        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    
    }

    /// <summary>
    /// This methods does the job to create tasks for posting free text invocies.
    /// </summary>
    /// <param name = "_contract"><c>METAMEXMoveRejectedLinesContract</c></param>
    private void postFreeTextInvTask(METAMEXMoveRejectedLinesContract   _contract)
    {
        LedgerJournalTrans                  ledgerJournalTrans;
        DimensionAttributeValuecombination  dimensionAttribute;
        int                                 bundlesize, totalRecords, totalTasks, i, j, task;
        Map                                 companyCustMap = new Map(Types::String, Types::String);
    
        LedgerJournalTable                  journalTable =   LedgerJournalTable::find(_contract.parmPrevJournalNum());

        if (!journalTable ||
            !journalTable.Posted)
        {
            throw error(strFmt("@MET:METAMEXJournalNotPostedError", journalTable.JournalNum));
        }

        totalTasks      =   _contract.parmTasks();
        if (totalTasks <= 0)
        {
            totalTasks = 1;
        }
        task = 1;

        while select count (RecId) from ledgerJournalTrans
            group by Company, LedgerDimension
            where ledgerJournalTrans.JournalNum == journalTable.JournalNum
        {
            totalrecords++;
        }

        bundleSize      =   real2int(roundUp((totalrecords / totalTasks), 1.0));
        BatchHeader batchHeader = this.getCurrentBatchHeader();

        while select Company, LedgerDimension from ledgerJournalTrans
            group by Company, LedgerDimension
            where ledgerJournalTrans.JournalNum == journalTable.JournalNum
        {
            select firstonly DisplayValue from dimensionAttribute
                where dimensionAttribute.RecId == ledgerJournalTrans.LedgerDimension;
            companyCustMap.insert(ledgerJournalTrans.Company, dimensionAttribute.DisplayValue);
            i++;
            if (i  == bundleSize || j == totalRecords)
            {
                task++;
                SysOperationServiceController createInvController = new SysOperationServiceController(
                                                                classStr(METAMEXCustFreeTextInvService),
                                                                methodStr(METAMEXCustFreeTextInvService, postInvoiceSubTask));
                createInvController.parmDialogCaption(strFmt("@MET:METAMEXPostFreeTextInvoicesSubTask", task, _contract.parmPrevJournalNum()));

                METAMEXCustFreeTextInvContract invContract = createInvController.getDataContractObject() as METAMEXCustFreeTextInvContract;
                invContract.parmBatchId(_contract.parmBatchId());
                invContract.parmJournalId(journalTable.JournalNum);
                invContract.getCompanyCustMap(companyCustMap);

                batchHeader.addRuntimeTask(createInvController, this.getCurrentBatchTask().RecId);
                companyCustMap = new Map(Types::String, Types::String);
                i = 0;
            }
            j++;
        }
        batchHeader.save();
    }

    /// <summary>
    /// Prepares the instance of the <c>METAMEXMoveRejectedLinesService</c> class to execute the
    /// <c>moveRejectedLines</c> method in parallel.
    /// </summary>
    /// <param name = "_contract"><c>METAMEXMoveRejectedLinesContract</c></param>
    /// <returns>
    /// An instance of the <c>SysOperationServiceController</c> class
    /// </returns>
    /// <remarks>
    /// This method uses the Sys Operations Framework to enable the parallel processing.
    /// </remarks>
    private SysOperationServiceController moveRejectedLinesController(METAMEXMoveRejectedLinesContract _contract)
    {
        SysOperationServiceController controller = new SysOperationServiceController(
                                                    classStr(METAMEXMoveRejectedLinesService),
                                                    methodStr(METAMEXMoveRejectedLinesService, moveRejectedLinesTask),
                                                    SysOperationExecutionMode::Synchronous);

        controller.parmDialogCaption(strFmt("@MET:METAMEXMovePaymentLinesPostTask", _contract.parmAction(),_contract.parmPrevJournalNum()));

        METAMEXMoveRejectedLinesContract contract = controller.getDataContractObject() as METAMEXMoveRejectedLinesContract;

        contract.parmAction(_contract.parmAction());
        contract.parmBatchId(_contract.parmBatchId());
        contract.parmPrevJournalNum(_contract.parmPrevJournalNum());
        contract.parmJournalName(_contract.parmJournalName());
        contract.parmJournalDesc(_contract.parmJournalDesc());
        contract.parmTasks(_contract.parmTasks());

        return controller;
    }

    /// <summary>
    /// Prepares the instance of the <c>METAMEXMoveRejectedLinesService</c> class to execute the
    /// <c>postFreeTextInvTask</c> method in parallel.
    /// </summary>
    /// <param name = "_contract"><c>METAMEXMoveRejectedLinesContract</c></param>
    /// <returns>
    /// An instance of the <c>SysOperationServiceController</c> class
    /// </returns>
    /// <remarks>
    /// This method uses the Sys Operations Framework to enable the parallel processing.
    /// </remarks>
    private SysOperationServiceController postFreeTextInvController(METAMEXMoveRejectedLinesContract _contract)
    {
        SysOperationServiceController controller = new SysOperationServiceController(
                                                        classStr(METAMEXMoveRejectedLinesService),
                                                        methodStr(METAMEXMoveRejectedLinesService, postFreeTextInvTask),
                                                        SysOperationExecutionMode::Synchronous);

        controller.parmDialogCaption(strFmt("@MET:METAMEXPostFreeTextInvoicesTask", _contract.parmPrevJournalNum()));

        METAMEXMoveRejectedLinesContract contract = controller.getDataContractObject() as METAMEXMoveRejectedLinesContract;

        contract.parmBatchId(_contract.parmBatchId());
        contract.parmPrevJournalNum(_contract.parmPrevJournalNum());
        contract.parmTasks(_contract.parmTasks());
        return controller;
    }
